import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import socialCards from "../plugins/social-cards/render-card.js";

const { renderCardPng } = socialCards;

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const rootDir = path.resolve(__dirname, "..");
const outputPath = path.join(rootDir, "static", "img", "social-card.png");

// Default 1200x630 Open Graph card used for the homepage and as the fallback
// image. Per-page cards are generated by plugins/social-cards after the build.
const png = renderCardPng({
  title: "Atmos",
  subtitle: "The runtime for infrastructure",
  description:
    "One consistent way to build, ship, and run Terraform, Kubernetes, and containers, identically on your laptop and in CI.",
});

mkdirSync(path.dirname(outputPath), { recursive: true });
writeFileSync(outputPath, png);
console.log(`Generated ${path.relative(rootDir, outputPath)}`);
